const raw = $json.stdout || '';
let input = $json;
try {
  input = raw ? JSON.parse(raw) : $json;
} catch (error) {
  input = { schema_version: 1, gate_passed: false, errors: ['wrapper_output_invalid'] };
}
const fields = ['schema_version', 'run_id', 'gate_passed', 'intro_zh', 'summary_zh', 'field_descriptions_zh', 'health', 'retrieval', 'training', 'artifacts', 'errors'];
const output = {};
for (const field of fields) output[field] = input[field] ?? null;
return [{ json: output }];
